import boto3

bedrock = boto3.client('bedrock-runtime')

def embed_text(text):
    response = bedrock.invoke_model(
        model_id='amazon.titan-embed-text-v1',
        body={
            'inputText': text
        }
    )
    result = json.loads(response['body'].read())
    return result['embedding']

if __name__ == '__main__':
    audit_notes = 'Sample secret audit notes for embedding.'
    embedding = embed_text(audit_notes)
    print(f'Embedding: {embedding}')

import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    return False

def main():
    secret_label = 'Example secret label'
    secret_note = 'Example secret note'
    if check_unsafe_text(secret_label) or check_unsafe_text(secret_note):
        print('Unsafe text detected in secret label or note')
    else:
        print('No unsafe text detected')

if __name__ == '__main__':
    main()

